    const{loginname}=useContext(Contextapi)
    return ( 
<>
<section id="header">
    <div className="container">
        <div className="row">
            <div className="col-md-4">
                <h2>welcome to{loginname}</h2>
            </div>
            <div className="col-md-8">
                <h4><button>login..</button></h4>
            </div>
        </div>
    </div>

</section>


</>

     );
}

export default Header;
